
const defaultClasses=[];/* data rombel default kosong: tambah rombel dari menu Manajemen Hafalan atau impor Excel */
const defaultStudents=[];/* data anak default kosong: guru menambah anak sendiri atau impor Excel */
const defaultSurahs=[['An-Nas',1,6,'Target contoh'],['Al-Falaq',1,5,'Target contoh'],['Al-Ikhlas',1,4,'Target contoh'],['Al-Lahab',1,5,'Target contoh'],['Al-Ma’un',1,7,'Target contoh'],['Al-Kautsar',1,3,'Target contoh'],['Al-Quraisy',1,4,'Target contoh'],['Al-Fil',1,5,'Target contoh'],['Al-Humazah',1,9,'Target contoh'],['At-Takatsur',1,8,'Target contoh']];
let classes,students,surahs,logs,settings,modalMode,editingId=null,selectedClass=null,selectedHafalanStudent=null;
function load(){
  const bad=[];
  const rd=k=>{let raw=null;try{raw=HKLS.getItem(k)}catch(e){}if(raw==null)return{miss:true};try{return{v:JSON.parse(raw)}}catch(e){bad.push(k);try{if(HKLS.getItem('hkCorrupt_'+k)==null)HKLS.setItem('hkCorrupt_'+k,raw)}catch(_){}return{miss:true}}};
  const rows=a=>Array.isArray(a)&&a.every(x=>x&&typeof x==='object'&&!Array.isArray(x));
  const arr=(k)=>{const r=rd(k);if(r.miss)return null;if(rows(r.v))return r.v;bad.push(k);try{if(HKLS.getItem('hkCorrupt_'+k)==null)HKLS.setItem('hkCorrupt_'+k,JSON.stringify(r.v))}catch(_){}return null};
  classes=arr('hkClasses')||defaultClasses;
  const st=arr('hkStudents');students=st||[];
  surahs=arr('hkSurahs')||defaultSurahs.map((s,i)=>({id:i+1,name:s[0],start:s[1],end:s[2],note:s[3]}));
  const lg=arr('hkLogs');logs=lg||[];
  const se=rd('hkSettings');settings=(se.v&&typeof se.v==='object'&&!Array.isArray(se.v))?se.v:{};
  if(bad.length){window.__hkCorrupt=bad.slice();setTimeout(()=>{try{toast('Data '+bad.join(', ')+' rusak dan diganti data awal. Salinan data rusak disimpan dengan nama hkCorrupt_* di penyimpanan browser.')}catch(e){}},900)}
  settings=Object.assign({name:'Guru Tahfidz',school:'SDN 01 Papahan',year:'2026/2027',appName:'Hafalanku',logo:null},settings);if(!settings.school)settings.school='SDN 01 Papahan';applyBrand()}
function __saveRaw(){HKLS.hkClasses=JSON.stringify(classes);HKLS.hkStudents=JSON.stringify(students);HKLS.hkSurahs=JSON.stringify(surahs);HKLS.hkLogs=JSON.stringify(logs);HKLS.hkSettings=JSON.stringify(settings)}
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function className(id){return classes.find(c=>c.id==id)?.name||'Tanpa kelas'}function getSurah(name){return surahs.find(s=>s.name===name)}function hasAyatModel(s){return !!(s&&(s.hafalanLevel||(s.surahProgress&&Object.keys(s.surahProgress).length)))}
function needsRepeat(st){return st==='Perlu murajaah'||st==='Belum lancar'||st==='Belum hafal'}
function pct(s){if(s.tamat)return 100;if(hasAyatModel(s)){try{return hfLevelStats(s,defaultHafalanLevel(s)).pct}catch(e){return 0}}{const v=Math.round((Number(s.done||0)/Math.max(1,Number(s.target||1)))*100);return Number.isFinite(v)?Math.max(0,Math.min(100,v)):0}}function pctF(s){if(s.tamat)return 100;if(hasAyatModel(s)){try{const x=hfLevelStats(s,defaultHafalanLevel(s));if(!x.total)return 0;return x.hafal>=x.total?100:Math.min(99,Math.floor(x.hafal/x.total*100))}catch(e){return 0}}return pct(s)}function initials(name){return name.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase()}function today(){let d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}function niceDate(d){if(!d)return '—';return new Date(d+'T00:00:00').toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'})}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2600)}function toggleNav(){$('sidebar').classList.toggle('open');$('navoverlay').classList.toggle('show')}
/* ===== Pemisahan data alumni: hanya menu Alumni yang memakai data lulusan ===== */
function hkOffIds(){const s=new Set();students.forEach(x=>{if(x&&x.alumni)s.add(String(x.id))});return s}
function nonAlumni(){return students.filter(s=>!s.alumni)}
function activeStudents(){return students.filter(s=>s.status!=='Nonaktif')}
function histLogs(){const off=hkOffIds();return logs.filter(l=>l&&!l.auto&&!off.has(String(l.studentId)))}
function activeLogs(){const ok=new Set(students.filter(s=>s&&s.status!=='Nonaktif'&&!s.alumni).map(s=>String(s.id)));return logs.filter(l=>l&&!l.auto&&ok.has(String(l.studentId)))}
function activeExams(){const off=hkOffIds();return exams.filter(e=>!off.has(String(e.studentId)))}
function go(v,btn){document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));$('view-'+v).classList.add('active');document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===v));let titles={dashboard:'Dashboard',kelas:'Manajemen Hafalan',capaian:'Capaian Hafalan',siswa:'Data Anak',riwayat:'Riwayat Kemajuan',surat:'Target Surat & Ayat',laporan:'Laporan Hafalan',alumni:'Alumni',pengaturan:'Pengaturan'};$('pagetitle').textContent=titles[v];$('crumb').textContent=titles[v];$('sidebar').classList.remove('open');$('navoverlay').classList.remove('show');if(v==='kelas')renderClasses();if(v==='capaian')renderAchievements();if(v==='siswa')renderStudents();if(v==='riwayat')renderHistory();if(v==='surat')renderSurahs();if(v==='laporan')renderReports();if(v==='pengaturan'){ $('settingName').value=settings.name;$('settingSchool').value=settings.school;$('settingYear').value=settings.year;$('settingPrincipal').value=settings.principal||'';$('settingPrincipalNip').value=settings.principalNip||'';$('settingAppName').value=settings.appName;pendingLogo=settings.logo;$('logoPreview').src=pendingLogo||LOGO_FULL;pendingSchoolLogo=settings.schoolLogo||null;pendingFormLogo=settings.formLogo||null;refreshLogoPreviews()}}
function cardHTML(c){let list=students.filter(s=>s.classId===c.id),avg=list.length?Math.round(list.reduce((a,s)=>a+pct(s),0)/list.length):0;let colors=['#e8f4ef','#e9fbf4','#fff4e3','#f1fbf8','#fff0f1'];let ix=(c.id-1)%colors.length;return `<article class="class-card"><div class="class-head"><div class="class-emblem" style="background:${colors[ix]}">▤</div><div><h4>${esc(c.name)}</h4><small>${esc(c.year||settings.year)} · ${esc(c.teacher||c.level||'Rombongan belajar')} · ${list.length} anak</small></div><button class="more" onclick="openClass(${c.id})">···</button></div><div class="class-progress"><span>Rata-rata capaian</span><b style="color:#3d4ef0">${avg}%</b></div><div class="bar"><span style="width:${avg}%"></span></div><div class="class-foot"><div class="faces">${list.slice(0,4).map(s=>`<span class="face">${initials(s.name)}</span>`).join('')||'<span class="face">＋</span>'}</div><small>${list.length} anak terdaftar</small><button class="linkbtn" onclick="showClass(${c.id})">Detail →</button></div></article>`}
function renderClasses(){let q=($('classSearch')?.value||'').toLowerCase(),f=$('classFilter')?.value||'all';let arr=classes.filter(c=>c.name.toLowerCase().includes(q)&&(f==='all'||classGradeName(c)===f));$('allClasses').innerHTML=arr.map(cardHTML).join('')||'<div class="empty">Belum ada kelas. Tambahkan kelas terlebih dahulu.</div>';if(selectedClass)showClass(selectedClass)}
/* Katalog kurikulum per juz. Nomor level diberi urutan otomatis lintas juz.
   Menambah juz baru = tambah satu entri di JUZ_CATALOG (tiap juz dibagi ke beberapa level,
   tiap level berisi pasangan [nama surat, jumlah ayat]). Formulir scan, ujian kenaikan level,
   dan label level mengikuti otomatis. Nama surat dipakai sebagai kunci data anak: jangan diubah ejaannya. */
const JUZ_CATALOG=[
 {juz:'30',title:'Juz 30',levels:[
  [['An-Nas',6],['Al-Falaq',5],['Al-Ikhlas',4],['Al-Lahab',5],['An-Nashr',3],['Al-Kafirun',6],['Al-Kautsar',3],['Al-Ma’un',7],['Al-Quraisy',4],['Al-Fil',5],['Al-Humazah',9],['Al-‘Asr',3]],
  [['At-Takatsur',8],['Al-Qari’ah',11],['Al-‘Adiyat',11],['Az-Zalzalah',8],['Al-Bayyinah',8],['Al-Qadr',5],['Al-‘Alaq',19],['At-Tin',8],['Al-Insyirah',8],['Ad-Dhuha',11]],
  [['Al-Lail',21],['Asy-Syams',15],['Al-Balad',20],['Al-Fajr',30],['Al-Ghasyiyah',26],['Al-A’la',19],['Ath-Thariq',17],['Al-Buruj',22]],
  [['Al-Insyiqaq',25],['Al-Muthaffifin',36],['Al-Infithar',19],['At-Takwir',29],['‘Abasa',42],['An-Nazi’at',46],['An-Naba’',40]]
 ]}
];
const HAFALAN_CURRICULUM={},LEVEL_JUZ={};
JUZ_CATALOG.forEach(j=>j.levels.forEach(l=>{const n=String(Object.keys(HAFALAN_CURRICULUM).length+1);HAFALAN_CURRICULUM[n]=l;LEVEL_JUZ[n]=j.juz}));

/* Manajemen Level: susunan surat per level bisa diubah & disimpan (hkLevelMap). Kunci data anak tetap nama surat. */
const LV_MASTER=new Map(),LV_DEFAULT={};
Object.keys(HAFALAN_CURRICULUM).forEach(l=>{LV_DEFAULT[l]=HAFALAN_CURRICULUM[l].map(x=>x[0]);HAFALAN_CURRICULUM[l].forEach(([n,m])=>LV_MASTER.set(n,m))});
function lvCurrent(){const o={};Object.keys(HAFALAN_CURRICULUM).forEach(l=>o[l]=HAFALAN_CURRICULUM[l].map(x=>x[0]));return o}
function lvValid(m){try{const keys=Object.keys(LV_DEFAULT),seen=new Set();for(const l of keys){if(!Array.isArray(m[l])||!m[l].length)return false;for(const n of m[l]){if(!LV_MASTER.has(n)||seen.has(n))return false;seen.add(n)}}return seen.size===LV_MASTER.size}catch(e){return false}}
function lvApply(m){Object.keys(HAFALAN_CURRICULUM).forEach(l=>{const a=HAFALAN_CURRICULUM[l];a.length=0;m[l].forEach(n=>a.push([n,LV_MASTER.get(n)]))})}
try{const m=JSON.parse(HKLS.hkLevelMap||'null');if(m&&lvValid(m))lvApply(m)}catch(e){}
function lvLabel(l){return 'Level '+l+(JUZ_CATALOG.length>1&&LEVEL_JUZ[l]?' · Juz '+LEVEL_JUZ[l]:'')}
function defaultHafalanLevel(s){if(s.hafalanLevel)return s.hafalanLevel;let c=classes.find(x=>String(x.id)===String(s.classId));let g=Number(c?.grade)||parseInt(c?.name)||1;return g<=2?'1':g<=3?'2':g<=4?'3':'4'}
function studentHafalanPanel(s){let level=defaultHafalanLevel(s),catalog=HAFALAN_CURRICULUM[level]||HAFALAN_CURRICULUM['1'],progress=s.surahProgress||{},records=Object.values(progress),done=records.filter(x=>x.status==='Hafal').length,notDone=records.filter(x=>x.status==='Belum hafal').length;return `<div class="hafalan-inline-panel" id="studentHafalanPanel"><div class="hafalan-inline-head"><div><h4>Catatan hafalan — ${esc(s.name)}</h4><p>Pilih level, lalu tentukan surat dan rentang ayat yang disetorkan. Status setiap surat tersimpan untuk anak ini.</p></div><button class="btn light small" onclick="closeStudentHafalan()">Tutup detail</button></div><div class="hafalan-level-tabs">${Object.keys(HAFALAN_CURRICULUM).map(l=>`<button class="hafalan-level-tab ${l===level?'active':'locked'}" onclick="setStudentHafalanLevel(${s.id},'${l}')">${lvLabel(l)}</button>`).join('')}</div><div class="hafalan-count"><span>Surat di level ini: <b>${catalog.length}</b></span><span>Sudah hafal: <b>${done}</b></span><span>Belum hafal: <b>${notDone}</b></span></div><p class="hafalan-level-note">Level ${esc(level)} · Rentang ayat dapat disesuaikan jika setoran hanya sebagian surat.</p><div class="hafalan-surah-list">${catalog.map(([name,maxAyat],i)=>{let r=progress[name]||{},status=r.status||'Belum dicatat',from=r.from||1,to=r.to||maxAyat;return `<div class="hafalan-surah-row"><div class="hafalan-surah-name">${i+1}. ${esc(name)}<small>${maxAyat} ayat · ${r.date?'Terakhir dicatat '+niceDate(r.date):'Belum ada catatan'}</small>${r.status?`<span class="hafalan-saved">${r.status==='Hafal'?'✓ Hafal':'◷ Belum hafal'} · ayat ${r.from}–${r.to}</span>`:''}</div><div class="hafalan-range"><input aria-label="Ayat awal ${esc(name)}" id="hf-from-${s.id}-${i}" type="number" min="1" max="${maxAyat}" value="${from}"><span>–</span><input aria-label="Ayat akhir ${esc(name)}" id="hf-to-${s.id}-${i}" type="number" min="1" max="${maxAyat}" value="${to}"></div><select class="hafalan-status-select" id="hf-status-${s.id}-${i}" aria-label="Status ${esc(name)}"><option value="Belum dicatat" ${status==='Belum dicatat'?'selected':''}>Pilih status…</option><option value="Hafal" ${status==='Hafal'?'selected':''}>✓ Hafal</option><option value="Belum hafal" ${status==='Belum hafal'?'selected':''}>Belum hafal</option></select><button class="hafalan-save-btn" onclick="saveStudentSurah(${s.id},'${level}',${i},'${name.replace(/'/g,"\\'")}',${maxAyat})">Simpan</button></div>`}).join('')}</div>`}
function showClass(id){selectedClass=id;let c=classes.find(x=>String(x.id)===String(id));if(!c)return;let list=students.filter(s=>String(s.classId)===String(id));$('classDetail').style.display='block';$('classDetail').innerHTML=`<div class="panelhead"><div><h3>${esc(c.name)} — Daftar Hafalan Anak</h3><p>${esc(c.desc||'Pilih nama anak untuk melihat level dan mencatat status surat yang dihafal.')}</p></div><button class="btn" onclick="openProgress(null,${id})">＋ Catat Setoran</button></div><div class="tablewrap"><table class="table"><thead><tr><th>Nama anak</th><th>Level</th><th>Hafalan terakhir</th><th>Capaian</th><th>Aksi</th></tr></thead><tbody>${list.map(s=>{let level=defaultHafalanLevel(s),rec=Object.values(s.surahProgress||{}),count=rec.filter(r=>r.status==='Hafal').length;return `<tr><td><div class="student"><span class="face" style="background:#e9ecfe">${initials(s.name)}</span><div><b>${esc(s.name)}</b><small>${s.nis?'NIS '+esc(s.nis)+' · ':''}${esc(className(s.classId))}</small></div></div></td><td><span class="hafalan-level-pill">Level ${esc(level)}</span></td><td>${rec.length?`${count} surat hafal`:'Belum ada catatan'}<small style="display:block;color:#8a9d98;margin-top:4px">Target umum: ${esc(s.surah||'—')} ayat ${s.start||1}–${s.target||0}</small></td><td class="progresscell"><div class="bar"><span style="width:${pct(s)}%"></span></div><small>${pct(s)}% target umum</small></td><td><button class="btn small" onclick="openStudentHafalan(${s.id})">${selectedHafalanStudent===s.id?'Tutup detail':'Kelola hafalan'}</button></td></tr>`}).join('')||'<tr><td colspan="5" class="empty"><div class="empty-in">Belum ada anak di kelas ini.</div></td></tr>'}</tbody></table></div>${selectedHafalanStudent?studentHafalanPanel(list.find(s=>s.id===selectedHafalanStudent)||students.find(s=>s.id===selectedHafalanStudent)):''}`;if(selectedHafalanStudent){setTimeout(()=>{$('studentHafalanPanel')?.scrollIntoView({behavior:'smooth',block:'start'})},50)}else $('classDetail').scrollIntoView({behavior:'smooth',block:'start'})}
function openStudentHafalan(id){selectedHafalanStudent=selectedHafalanStudent===id?null:id;showClass(selectedClass)}
function closeStudentHafalan(){selectedHafalanStudent=null;showClass(selectedClass)}
function setStudentHafalanLevel(id,level){let s=students.find(x=>String(x.id)===String(id));if(!s)return;s.hafalanLevel=level;save();showClass(selectedClass)}
function saveStudentSurah(id,level,index,name,maxAyat){let s=students.find(x=>String(x.id)===String(id));if(!s)return;let from=Number($(`hf-from-${id}-${index}`).value),to=Number($(`hf-to-${id}-${index}`).value),status=$(`hf-status-${id}-${index}`).value;if(!Number.isInteger(from)||!Number.isInteger(to)||from<1||to<from||to>maxAyat){toast(`Rentang ayat ${name} harus antara 1–${maxAyat}, dan ayat akhir tidak boleh lebih kecil.`);return}if(!['Hafal','Belum hafal'].includes(status)){toast('Pilih status Hafal atau Belum hafal terlebih dahulu.');return}s.hafalanLevel=level;s.surahProgress=s.surahProgress||{};let rec={level,surah:name,from,to,status,date:today()};s.surahProgress[name]=rec;logs.push({id:Date.now(),studentId:s.id,studentName:s.name,classId:s.classId,date:today(),surah:name,from,to,status,note:`Level ${level} · dicatat dari Manajemen Hafalan`});save();renderDashboard();renderHistory();renderReports();showClass(selectedClass);toast(`Catatan ${name} untuk ${s.name} berhasil disimpan.`)}
function studentRow(s,actions=true){let p=pct(s);return `<tr><td><div class="student"><span class="face" style="background:#e9ecfe">${initials(s.name)}</span><div><b>${esc(s.name)}</b><small>${s.nis?'NIS '+esc(s.nis):'ID anak #'+s.id}</small></div></div></td><td>${esc(className(s.classId))}</td><td>${esc(s.surah)} <small style="color:#92a19d">(${s.start}–${s.target})</small></td><td class="progresscell"><div class="bar"><span style="width:${p}%"></span></div><small>${s.done||0}/${s.target} ayat · ${p}%</small></td><td><span class="pill ${p<30?'orange':p>=100?'purple':''}">${p>=100?'Target tercapai':pctF(s)>=25?'Berkembang':'Mulai menghafal'}</span></td>${actions?`<td><button class="linkbtn" onclick="openProgress(${s.id})">＋ Setor</button> <button class="linkbtn" onclick="editStudent(${s.id})">Edit</button></td>`:''}</tr>`}
const GRADS=['linear-gradient(135deg,#5a6af7,#3d4ef0)','linear-gradient(135deg,#7b87f8,#4a5bf6)','linear-gradient(135deg,#ff9b5e,#f0702b)','linear-gradient(135deg,#3d4ef0,#2a37cf)'],AVS=['#0f6b54','#2f9174','#c98a2b','#0d5645','#1d8a6b','#b8791f','#0a7a63'];
const IC_PLUS='<svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg>',IC_EDIT='<svg viewBox="0 0 24 24"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z"/></svg>';
const openCards=new Set(),IC_CHEV='<svg viewBox="0 0 24 24"><path d="M6 9l6 6 6-6"/></svg>',IC_PEN='<svg viewBox="0 0 24 24"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z"/></svg>';
function toggleCard(id){openCards.has(id)?openCards.delete(id):openCards.add(id);renderStudents()}
function renderStudents(){let q=($('studentSearch')?.value||'').toLowerCase().trim();let groups=classes.map(c=>({c,list:students.filter(s=>s.classId==c.id)}));let orphan=students.filter(s=>!classes.some(c=>c.id==s.classId));if(orphan.length)groups.push({c:{id:0,name:'Tanpa kelas'},list:orphan});let shown=0;let html=groups.map(({c,list},gi)=>{let all=list.length,f=q?list.filter(s=>s.name.toLowerCase().includes(q)||c.name.toLowerCase().includes(q)):list;if(q&&!f.length)return'';shown+=f.length;let isOpen=q?true:openCards.has(c.id);let avg=all?Math.round(list.reduce((x,s)=>x+pct(s),0)/all):0;return `<div class="sc-card ${isOpen?'open':''}"><div class="sc-top" style="--g:${GRADS[gi%GRADS.length]}" onclick="toggleCard(${c.id})"><div class="sc-head"><div><h4>${esc(c.name)}</h4><p>${esc(c.desc||'Daftar anak dan capaian hafalan')}</p></div><div class="sc-headbtns">${c.id?`<button class="sc-hbtn" title="Edit kelas" onclick="event.stopPropagation();openClass(${c.id})">${IC_PEN}</button>`:''}<span class="sc-hbtn sc-chev">${IC_CHEV}</span></div></div><div class="sc-chips"><div class="sc-chip"><b>${all}</b>Anak</div><div class="sc-chip"><b>${avg}%</b>Rata-rata</div><span class="sc-hint">${isOpen?'Ketuk untuk menutup':'Ketuk untuk melihat nama'}</span></div></div><div class="sc-body"><div class="sc-list">${f.map(s=>{let p=pct(s),av=AVS[(s.id||0)%AVS.length];return `<div class="sc-item"><span class="face" style="--av:${av}">${initials(s.name)}</span><div class="sc-info"><b>${esc(s.name)}</b>${s.nis?`<span class="sc-nis">NIS ${esc(s.nis)}</span>`:''}<span class="sc-tag">${esc(s.surah)}</span></div><div class="ring" style="--p:${p};--c:${p>=100?'#3d4ef0':p>=25?'#6b79f7':'#ff8a4c'}"><span>${p}%</span></div><div class="sc-acts"><button class="sc-btn" title="Catat setoran" onclick="openProgress(${s.id})">${IC_PLUS}</button><button class="sc-btn" title="Edit data anak" onclick="editStudent(${s.id})">${IC_EDIT}</button></div></div>`}).join('')||'<div class="sc-empty">Belum ada anak di kelas ini.</div>'}</div>${c.id?`<button class="sc-add" onclick="openBulk(${c.id})">＋ Tambah anak ke ${esc(c.name)}</button>`:''}</div></div>`}).join('');$('studentCards').innerHTML=html||'<div class="panel empty" style="grid-column:1/-1">Data anak tidak ditemukan.</div>';$('studentCountLabel').textContent=q?`Menampilkan ${shown} dari ${students.length} anak.`:`${students.length} anak di ${classes.length} kelas.`}
function renderHistory(){let d=$('historyDate')?.value||'',c=$('historyClass')?.value||'all';let list=[...activeLogs()].reverse().filter(l=>(!d||l.date===d)&&(c==='all'||String(l.classId)===c));$('historyRows').innerHTML=list.map(l=>`<tr><td>${niceDate(l.date)}</td><td><b>${esc(l.studentName)}</b></td><td>${esc(className(l.classId))}</td><td>${esc(l.surah)} ${l.from}–${l.to}</td><td><span class="pill ${needsRepeat(l.status)?'orange':''}">${esc(l.status)}</span></td><td>${esc(l.note||'—')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty"><div class="empty-in">Belum ada catatan untuk filter ini.</div></td></tr>'}
function renderSurahs(){$('surahRows').innerHTML=surahs.map(s=>`<tr><td><b>${esc(s.name)}</b></td><td>Ayat ${s.start}–${s.end}</td><td>${Math.max(0,s.end-s.start+1)} ayat</td><td>${esc(s.note||'—')}</td><td><button class="linkbtn" onclick="editSurah(${s.id})">Edit</button> <button class="linkbtn" style="color:#e35464" onclick="deleteSurah(${s.id})">Hapus</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty"><div class="empty-in">Belum ada target surat.</div></td></tr>'}
let achievementTab='sekolah';
const ACH_LEVELS=[
 {n:1,name:'0–24%',min:0,max:24,desc:'Mulai membangun kebiasaan hafalan',cls:'level-1'},
 {n:2,name:'25–49%',min:25,max:49,desc:'Sedang menambah hafalan',cls:'level-2'},
 {n:3,name:'50–74%',min:50,max:74,desc:'Progres hafalan sudah kuat',cls:'level-3'},
 {n:4,name:'75–100%',min:75,max:100,desc:'Mendekati atau mencapai target',cls:'level-4'}
];
function studentLevel(s){let p=pctF(s);return ACH_LEVELS.find(l=>p>=l.min&&p<=l.max)||ACH_LEVELS[0]}
function setAchievementTab(tab,btn){achievementTab=tab;document.querySelectorAll('[data-ach-tab]').forEach(b=>b.classList.toggle('active',b.dataset.achTab===tab));renderAchievements()}
function achievementSummary(kids){let avg=kids.length?Math.round(kids.reduce((sum,s)=>sum+pct(s),0)/kids.length):0;return {avg,completed:kids.filter(s=>pct(s)>=100).length,levels:ACH_LEVELS.map(l=>({...l,count:kids.filter(s=>studentLevel(s).n===l.n).length}))}}
function achievementLevelCards(kids){let sum=achievementSummary(kids);return `<div class="level-grid">${sum.levels.map(l=>`<div class="level-card"><div class="level-kicker">Level ${l.n}</div><h3>${l.name}</h3><p>${l.min}%–${l.max}% capaian target</p><strong>${l.count}</strong> <span style="font-size:11px;color:#7a918b">anak</span></div>`).join('')}</div>`}
function achTarget(s){if(s.tamat)return 'Tamat semua level';if(hasAyatModel(s)){const l=defaultHafalanLevel(s);return 'Level '+l+' · '+(HAFALAN_CURRICULUM[l]||[]).length+' surat'}return (s.surah||'—')+' ('+(s.start||1)+'–'+(s.target||0)+')'}
function achCap(s){if(s.tamat)return 'Tamat · 100%';if(hasAyatModel(s)){const x=hfLevelStats(s,defaultHafalanLevel(s));return x.hafal+'/'+x.total+' ayat · '+pct(s)+'%'}return (s.done||0)+'/'+(s.target||0)+' ayat · '+pct(s)+'%'}
function achievementStudentTable(kids){return `<div class="ach-table-wrap"><table class="ach-table"><thead><tr><th>Nama anak</th><th>Rombel</th><th>Target</th><th>Capaian</th><th>Level</th></tr></thead><tbody>${kids.map(s=>{let l=studentLevel(s);return `<tr><td><b>${esc(s.name)}</b>${s.nis?`<br><small style="color:#6b7280">NIS ${esc(s.nis)}</small>`:''}</td><td>${esc(className(s.classId))}</td><td>${esc(achTarget(s))}</td><td>${esc(achCap(s))}</td><td><span class="level-badge ${l.cls}">Level ${l.n} · ${l.name}</span></td></tr>`}).join('')||'<tr><td colspan="5" class="empty"><div class="empty-in">Belum ada data anak.</div></td></tr>'}</tbody></table></div>`}
function classGradeName(c){if(c.grade)return 'Kelas '+c.grade;let text=String(c.name||'');let m=text.match(/(?:kelas\s*)?(\d+)/i);return m?'Kelas '+m[1]:'Kelas belum ditentukan'}
function refreshClassFilter(){let el=$('classFilter');if(!el)return;let current=el.value||'all',grades=[...new Set(classes.map(classGradeName))].sort((a,b)=>a.localeCompare(b,'id',{numeric:true}));el.innerHTML='<option value="all">Semua tingkat</option>'+grades.map(g=>`<option value="${esc(g)}">${esc(g)}</option>`).join('');if(grades.includes(current))el.value=current}
function renderAchievements(){
 const kids=students.filter(s=>s.status!=='Nonaktif'),sum=achievementSummary(kids),overall=sum.avg;
 const stats=achievementTab==='sekolah'?[['Rata-rata capaian sekolah',overall+'%'],['Jumlah rombel',classes.length],['Anak mencapai target',sum.completed],['Total peserta didik',kids.length]]:
 achievementTab==='rombel'?[['Rombel terdaftar',classes.length],['Rata-rata capaian',overall+'%'],['Anak mencapai target',sum.completed],['Total peserta didik',kids.length]]:[['Tingkat kelas',new Set(classes.map(classGradeName)).size],['Rata-rata capaian',overall+'%'],['Anak mencapai target',sum.completed],['Total peserta didik',kids.length]];
 $('achievementStats').innerHTML=stats.map(x=>`<div class="stat"><div class="stat-top"><small>${esc(x[0])}</small></div><h3>${esc(x[1])}</h3></div>`).join('');
 let cards='';
 if(achievementTab==='sekolah'){
   cards=`<div class="panel"><div class="panelhead"><div><h3>Distribusi level hafalan seluruh sekolah</h3><p>Ringkasan jumlah peserta didik pada setiap level berdasarkan progres target ayat.</p></div></div>${achievementLevelCards(kids)}</div>`;
 }else if(achievementTab==='rombel'){
   cards=classes.map(c=>{let ck=kids.filter(s=>String(s.classId)===String(c.id)),cs=achievementSummary(ck);return `<article class="ach-class"><div class="ach-class-top"><div><h3>${esc(c.name)}</h3><p>${esc(c.year||settings.year)} · ${ck.length} peserta didik · ${cs.completed} mencapai target</p></div><div class="ach-percent">${cs.avg}%</div></div><div class="bar" style="height:9px;margin:13px 0 8px"><span style="width:${cs.avg}%"></span></div><div class="ach-levels">${cs.levels.map(l=>`<span>Level ${l.n} ${l.name}: <b>${l.count}</b></span>`).join('')}</div><button class="btn secondary small" style="margin-top:14px" onclick="showAchievementRombel(${JSON.stringify(String(c.id))})">Lihat daftar anak</button></article>`}).join('')||'<div class="empty">Belum ada rombel. Tambahkan kelas/rombel terlebih dahulu.</div>';
   cards+=`<div id="achievementRombelDetail"></div>`;
 }else{
   const groups={};classes.forEach(c=>{let key=classGradeName(c);(groups[key]||(groups[key]=[])).push(c)});
   cards=Object.keys(groups).sort((a,b)=>a.localeCompare(b,'id',{numeric:true})).map(g=>{let ids=groups[g].map(c=>String(c.id)),ck=kids.filter(s=>ids.includes(String(s.classId))),cs=achievementSummary(ck);return `<article class="ach-class"><div class="ach-class-top"><div><h3>${esc(g)}</h3><p>${groups[g].map(c=>esc(c.name)).join(' · ')} · ${ck.length} peserta didik</p></div><div class="ach-percent">${cs.avg}%</div></div><div class="bar" style="height:9px;margin:13px 0 8px"><span style="width:${cs.avg}%"></span></div><div class="ach-levels">${cs.levels.map(l=>`<span>Level ${l.n} ${l.name}: <b>${l.count}</b></span>`).join('')}</div></article>`}).join('')||'<div class="empty">Belum ada data kelas.</div>';
 }
 $('achievementCards').innerHTML=cards;
 if(achievementTab==='sekolah')$('achievementDetails').innerHTML='';else $('achievementDetails').innerHTML='';
}
function showAchievementRombel(classId){let c=classes.find(x=>String(x.id)===String(classId));if(!c)return;let kids=students.filter(s=>String(s.classId)===String(c.id)&&s.status!=='Nonaktif');let el=$('achievementRombelDetail');if(!el)return;el.innerHTML=`<div class="panel" style="margin-top:16px"><div class="panelhead"><div><h3>Capaian ${esc(c.name)}</h3><p>Daftar level dan progres hafalan setiap anak.</p></div><button class="btn light small" onclick="document.getElementById('achievementRombelDetail').innerHTML=''">Tutup</button></div>${achievementStudentTable(kids)}</div>`;el.scrollIntoView({behavior:'smooth',block:'start'})}
/* ===== Cetak laporan capaian hafalan: satu sekolah · level · kelas · rombel · anak ===== */
var RP_TYPES=[
{id:'sekolah',label:'Satu Sekolah',badge:'Rekomendasi',unit:'laporan sekolah',desc:'Rekap seluruh anak dengan ringkasan, sebaran level, dan rekap rombel.',icon:'<path d="M3 10l9-6 9 6"/><path d="M5 10v9h14v-9"/><path d="M10 19v-5h4v5"/>'},
{id:'level',label:'Per Level',unit:'laporan level',desc:'Daftar anak dan rekap per surat untuk setiap level hafalan.',icon:'<path d="M4 5h6a2 2 0 0 1 2 2v12a2 2 0 0 0-2-2H4z"/><path d="M20 5h-6a2 2 0 0 0-2 2v12a2 2 0 0 1 2-2h6z"/>'},
{id:'kelas',label:'Per Kelas',unit:'laporan kelas',desc:'Rekap per tingkat kelas dengan daftar anak di setiap rombel.',icon:'<path d="M2 9l10-5 10 5-10 5z"/><path d="M6 11v5c0 1.5 3 3 6 3s6-1.5 6-3v-5"/>'},
{id:'rombel',label:'Per Rombel',unit:'laporan rombel',desc:'Satu halaman per rombel dengan daftar anak dan tanda tangan wali kelas.',icon:'<circle cx="9" cy="8" r="3"/><circle cx="17" cy="9" r="2.5"/><path d="M3 20c0-3 3-5 6-5s6 2 6 5"/><path d="M15 15c2.5 0 5 1.5 5 4"/>'},
{id:'anak',label:'Per Anak',unit:'rapor anak',desc:'Rapor hafalan per anak: rincian surat, ayat, dan riwayat setoran.',icon:'<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 3.6-7 8-7s8 3 8 7"/>'}
];
