/* ---------- data & perhitungan ---------- */
function rpClass(id){return classes.find(c=>String(c.id)===String(id))}
function rpGradeOf(c){return c?(Number(c.grade)||parseInt(c.name,10)||0):0}
function rpTeacher(c){return c&&c.teacher?String(c.teacher).trim():''}
function rpTahfidz(){const n=String(settings.name||'').trim();if(n&&n.toLowerCase()!=='guru tahfidz')return n;const pf=document.querySelector('.profile b');return pf&&pf.textContent?String(pf.textContent).trim():''}
function rpTgl(){return new Date().toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'})}
function rpLevels(){return Object.keys(HAFALAN_CURRICULUM)}
function rpGrades(){return [...new Set(classes.map(c=>rpGradeOf(c)).filter(Boolean))].sort((a,b)=>a-b)}
function rpSortedClasses(){return classes.slice().sort((a,b)=>rpGradeOf(a)-rpGradeOf(b)||String(a.name).localeCompare(String(b.name),'id',{numeric:true}))}
function rpActive(){return students.filter(s=>s&&s.status!=='Nonaktif')}
function rpSortStudents(list){const ord=new Map(rpSortedClasses().map((c,i)=>[String(c.id),i]));return list.slice().sort((a,b)=>(ord.get(String(a.classId))??999)-(ord.get(String(b.classId))??999)||a.name.localeCompare(b.name,'id'))}
function rpStat(s){
 const l=defaultHafalanLevel(s),cat=HAFALAN_CURRICULUM[l]||[];
 const surahs=cat.map(([name,max])=>{const h=hfSurahStats(s,name,max).hafal;return{name,max,hafal:h,status:h>=max?'Tuntas':h>0?'Sebagian':'Belum'}});
 const total=cat.reduce((a,x)=>a+x[1],0),hafal=surahs.reduce((a,x)=>a+x.hafal,0),tamat=!!s.tamat;
 let ready=false;try{ready=!tamat&&!!ujState(s).ready}catch(e){}
 return{s,level:l,surahs,total,hafal,count:surahs.length,done:surahs.filter(x=>x.status==='Tuntas').length,pct:tamat?100:(hasAyatModel(s)?hfPct(hafal,total):pct(s)),pctF:pctF(s),ready,tamat};
}
function rpGet(s){return RPCACHE.get(String(s.id))||rpStat(s)}
function rpSum(st){const n=st.length;return{n,avg:n?Math.round(st.reduce((a,x)=>a+x.pct,0)/n):0,ready:st.filter(x=>x.ready).length,tamat:st.filter(x=>x.tamat).length}}
function rpMembers(t){
 const act=rpActive();let list;
 if(t.k==='sekolah')list=act;
 else if(t.k==='level')list=act.filter(s=>defaultHafalanLevel(s)===String(t.v));
 else if(t.k==='kelas')list=act.filter(s=>rpGradeOf(rpClass(s.classId))===Number(t.v));
 else if(t.k==='rombel')list=act.filter(s=>String(s.classId)===String(t.v.id));
 else return [t.v];
 return rpSortStudents(list);
}
function rpTargets(){
 const T=rpState.type;
 if(T==='sekolah')return [{k:'sekolah'}];
 if(T==='level')return (rpState.level==='all'?rpLevels():[rpState.level]).map(v=>({k:'level',v}));
 if(T==='kelas')return (rpState.grade==='all'?rpGrades():[Number(rpState.grade)]).map(v=>({k:'kelas',v}));
 if(T==='rombel')return rpSortedClasses().filter(c=>rpState.rombel==='all'||String(c.id)===String(rpState.rombel)).map(v=>({k:'rombel',v}));
 if(rpState.anak!=='all'){const s=students.find(x=>String(x.id)===String(rpState.anak));return s&&s.status!=='Nonaktif'&&rpClass(s.classId)?[{k:'anak',v:s}]:[]}
 return rpMembers({k:'sekolah'}).filter(s=>rpState.anakRombel==='all'||String(s.classId)===String(rpState.anakRombel)).map(v=>({k:'anak',v}));
}

/* ---------- komponen tampilan ---------- */
function rpBar(p){const v=Math.max(0,Math.min(100,Number(p)||0));return `<div class="rp-bar"><i style="width:${v}%"></i></div>`}
function rpLv(l){return `<span class="rp-lv rp-l${l}">Level ${l}</span>`}
function rpStatusInfo(x){const pf=x.pctF!=null?x.pctF:x.pct;if(x.tamat)return['Tamat','st-tamat'];if(x.ready)return['Siap ujian','st-siap'];if(pf>=25)return['Berkembang','st-kembang'];if(pf>0||x.pct>0||x.hafal>0)return['Mulai','st-mulai'];return['Belum mulai','st-belum']}
function rpStatusPill(x){const i=rpStatusInfo(x);return `<span class="st ${i[1]}">${i[0]}</span>`}
function rpSurahPill(t){const c=t==='Tuntas'?'st-siap':t==='Sebagian'?'st-kembang':'st-belum';return `<span class="st ${c}">${t}</span>`}
function rpSurahNames(l){return (HAFALAN_CURRICULUM[l]||[]).map(x=>x[0]).join(' · ')}
function rpBism(){return ''}
function rpHead(kicker,title,sub){
 return `${kopHTML(kopCur(),'doc')}<div class="rp-title"><small>${esc(kicker)}</small><h1>${esc(title)}</h1><p>${esc([sub,'Tahun ajaran '+(settings.year||'-')].filter(Boolean).join(' · '))}</p></div>`;
}
function rpKpi(items){return `<div class="rp-kpi">${items.map(([a,b,c])=>`<div class="rp-k"><small>${esc(a)}</small><b>${esc(b)}</b><span>${esc(c)}</span></div>`).join('')}</div>`}
function rpSec(title,meta,body){return `<div class="rp-sec"><div class="rp-sech"><h2>${esc(title)}</h2><span>${esc(meta||'')}</span></div>${body}</div>`}
function rpSub(title,meta){return `<div class="rp-sub"><h3>${esc(title)}</h3><span>${esc(meta||'')}</span></div>`}
function rpFoot(){return `<footer class="pfoot"><span>${esc(settings.school||'')} · Hafalanku</span><span>Dicetak ${esc(rpTgl())}</span></footer>`}
function rpPlace(){return '…………………, '+rpTgl()}
function rpSignKepala(){return{top:'Mengetahui,',role:'Kepala Sekolah',name:String(settings.principal||'').trim(),nip:String(settings.principalNip||'').trim()}}
function rpSignWali(c){return{top:rpPlace(),role:'Wali Kelas '+(c?c.name:''),name:rpTeacher(c)}}
function rpSignTahfidz(){return{top:rpPlace(),role:'Guru Tahfidz',name:rpTahfidz(),nip:String(settings.managerNip||'').trim()}}
function rpPaiMatch(t,c){if(!c)return false;const g=rpGradeOf(c),nm=String(c.name||'').toLowerCase().replace(/\s+/g,'');
 return String(t.kelas||'').toLowerCase().replace(/kelas/g,'').split(/[,;\/&]|\bdan\b/).some(x=>{x=x.replace(/\s+/g,'');if(!x)return false;
  const r=x.match(/^(\d+)[-–](\d+)$/);if(r)return g>=+r[1]&&g<=+r[2];return x===nm||x===String(g)})}
function rpSignPai(c){const a=(settings.paiTeachers||[]).filter(t=>rpPaiMatch(t,c)).map(t=>({top:rpPlace(),role:'Guru PAI dan BP',name:String(t.name||'').trim(),nip:String(t.nip||'').trim()}));return a.length?a:[{top:rpPlace(),role:'Guru PAI dan BP',name:'',nip:''}]}
function rpSign(boxes){return `<div class="rp-sign">${boxes.map(b=>`<div class="rp-sb"><div class="top">${b.top}</div><span class="role">${esc(b.role)}</span><div class="rp-ttd"></div><b class="nm">${b.name?esc(b.name):'…………………………………'}</b><span class="nip">NIP. ${b.nip?esc(b.nip):'……………………'}</span></div>`).join('')}</div>`}
function rpRombelTable(st){
 const rows=rpSortedClasses().map(c=>{const g=st.filter(x=>String(x.s.classId)===String(c.id));if(!g.length)return '';const A=rpSum(g);return `<tr><td><b>${esc(c.name)}</b></td><td>${esc(rpTeacher(c)||'—')}</td><td class="num">${A.n}</td><td class="num">${A.avg}%</td><td class="num">${A.ready}</td><td class="num">${A.tamat}</td><td class="bc">${rpBar(A.avg)}</td></tr>`}).join('');
 const T=rpSum(st);
 return `<table class="rp-t"><thead><tr><th>Rombel</th><th>Wali kelas</th><th class="num">Anak</th><th class="num">Rata-rata</th><th class="num">Siap ujian</th><th class="num">Tamat</th><th>Capaian</th></tr></thead><tbody>${rows}</tbody><tfoot><tr><td colspan="2">Jumlah</td><td class="num">${T.n}</td><td class="num">${T.avg}%</td><td class="num">${T.ready}</td><td class="num">${T.tamat}</td><td>${rpBar(T.avg)}</td></tr></tfoot></table>`;
}
function rpStuTable(list){
 if(!list.length)return '<div class="rp-empty">Belum ada anak pada bagian ini.</div>';
 return `<table class="rp-t"><thead><tr><th class="c" style="width:30px">No</th><th>Nama anak</th><th>Rombel</th><th class="c">Surat tuntas</th><th class="num">Ayat hafal</th><th>Capaian</th><th>Status</th></tr></thead><tbody>${list.map((x,i)=>`<tr><td class="c">${i+1}</td><td><b>${esc(x.s.name)}</b></td><td>${esc((rpClass(x.s.classId)||{}).name||'—')}</td><td class="c">${x.done}/${x.count}</td><td class="num">${x.hafal}/${x.total}</td><td class="bc"><div class="rp-cell">${rpBar(x.pct)}<span>${x.pct}%</span></div></td><td>${rpStatusPill(x)}</td></tr>`).join('')}</tbody></table>`;
}

/* ---------- halaman laporan ---------- */
function rpPageSekolah(){
 const st=rpMembers({k:'sekolah'}).map(rpGet),A=rpSum(st),grp=rpState.group;
 const lvCards=rpLevels().map(l=>{const g=st.filter(x=>x.level===l),S=rpSum(g),share=A.n?Math.round(g.length/A.n*100):0;return `<div class="rp-lvc"><div class="rp-lvt">${rpLv(l)}<span>${share}% anak</span></div><b>${S.n}<em>anak</em></b>${rpBar(S.avg)}<div class="rp-lvm"><span>Rata-rata <b>${S.avg}%</b></span><span>Siap ujian <b>${S.ready}</b></span></div><p>${esc(rpSurahNames(l))}</p></div>`}).join('');
 let secs='';
 if(grp==='kelas'){
  secs=rpGrades().map(gr=>{const g=st.filter(x=>rpGradeOf(rpClass(x.s.classId))===gr);if(!g.length)return '';const S=rpSum(g),nc=rpSortedClasses().filter(c=>rpGradeOf(c)===gr).length;return rpSub(`Kelas ${gr}`,`${nc} rombel · ${S.n} anak · rata-rata ${S.avg}%`)+rpRombelTable(g)}).join('');
 }else{
  secs=rpLevels().map(l=>{const g=st.filter(x=>x.level===l);if(!g.length)return '';const S=rpSum(g);return rpSub(lvLabel(l),`${S.n} anak · rata-rata ${S.avg}%`)+rpRombelTable(g)}).join('');
 }
 return `<section class="page">${rpBism()}${rpHead('Laporan satu sekolah','Capaian hafalan Juz 30',`Dikelompokkan menurut ${grp==='kelas'?'tingkat kelas':'level hafalan'} · ${rpSortedClasses().length} rombel · ${A.n} anak aktif`)}${rpKpi([['Anak aktif',A.n,'Mengikuti hafalan'],['Capaian rata-rata',A.avg+'%','Rata-rata seluruh anak'],['Siap ujian',A.ready,'Menunggu ujian kenaikan'],['Tamat',A.tamat,'Menuntaskan level terakhir']])}${rpSec('Sebaran level','Jumlah anak dan capaian per level hafalan',`<div class="rp-lvgrid">${lvCards}</div>`)}${rpSec(grp==='kelas'?'Rekap per tingkat kelas':'Rekap per level','Rincian rombel di setiap bagian',secs)}${rpSign([rpSignKepala()])}${rpFoot()}</section>`;
}
function rpPageLevel(l){
 const cat=HAFALAN_CURRICULUM[l]||[],st=rpMembers({k:'level',v:l}).map(rpGet),A=rpSum(st),ayat=cat.reduce((a,x)=>a+x[1],0);
 const surRows=cat.map(([name,max],i)=>{const t=st.filter(x=>x.surahs[i].status==='Tuntas').length,b=st.filter(x=>x.surahs[i].status==='Sebagian').length,n=st.length-t-b,p=st.length?Math.round(t/st.length*100):0;return `<tr><td class="c">${i+1}</td><td><b>${esc(name)}</b></td><td class="c">${max}</td><td class="num">${t}</td><td class="num">${b}</td><td class="num">${n}</td><td class="bc">${rpBar(p)}</td></tr>`}).join('');
 return `<section class="page">${rpBism()}${rpHead('Laporan per level',lvLabel(l),`${cat.length} surat · ${ayat} ayat dalam level ini`)}${rpKpi([['Anak di level',A.n,'Sesuai level saat ini'],['Capaian rata-rata',A.avg+'%','Rata-rata anak di level'],['Siap ujian',A.ready,'Menunggu ujian kenaikan'],['Tamat',A.tamat,'Menuntaskan level ini']])}${rpSec('Rekap per surat','Jumlah anak yang sudah tuntas, sebagian, atau belum',`<table class="rp-t"><thead><tr><th class="c" style="width:30px">No</th><th>Surat</th><th class="c">Ayat</th><th class="num">Tuntas</th><th class="num">Sebagian</th><th class="num">Belum</th><th>Progres tuntas</th></tr></thead><tbody>${surRows||'<tr><td colspan="7" class="c">Belum ada surat pada level ini.</td></tr>'}</tbody></table>`)}${rpSec('Daftar anak','Diurutkan menurut rombel dan nama',rpStuTable(st))}${rpSign([rpSignKepala()])}${rpFoot()}</section>`;
}
function rpPageKelas(gr){
 const cls=rpSortedClasses().filter(c=>rpGradeOf(c)===gr),st=rpMembers({k:'kelas',v:gr}).map(rpGet),A=rpSum(st);
 const blocks=cls.map(c=>{const g=st.filter(x=>String(x.s.classId)===String(c.id));if(!g.length)return '';return rpSub(`Rombel ${c.name}`,`Wali kelas: ${rpTeacher(c)||'belum diisi'} · ${g.length} anak`)+rpStuTable(g)}).join('');
 return `<section class="page">${rpBism()}${rpHead('Laporan per kelas',`Kelas ${gr}`,`${cls.length} rombel · ${A.n} anak aktif`)}${rpKpi([['Anak aktif',A.n,'Mengikuti hafalan'],['Capaian rata-rata',A.avg+'%','Rata-rata seluruh kelas'],['Siap ujian',A.ready,'Menunggu ujian kenaikan'],['Tamat',A.tamat,'Menuntaskan level terakhir']])}${rpSec('Rekap rombel','Capaian masing-masing rombel',rpRombelTable(st))}${rpSec('Daftar anak per rombel','Diurutkan menurut nama',blocks)}${rpSign([rpSignKepala(),...rpSignPai({grade:gr,name:String(gr)})])}${rpFoot()}</section>`;
}
function rpPageRombel(c){
 const st=rpMembers({k:'rombel',v:c}).map(rpGet),A=rpSum(st),g=rpGradeOf(c);
 const stack=st.length?rpLevels().filter(l=>st.some(x=>x.level===l)).map(l=>`<i class="lvs${l}" style="flex:${st.filter(x=>x.level===l).length}"></i>`).join(''):'<i style="flex:1;background:#eef3f1"></i>';
 const legend=rpLevels().map(l=>`<span><b class="lvs${l}"></b>Level ${l} · ${st.filter(x=>x.level===l).length} anak</span>`).join('');
 return `<section class="page">${rpBism()}${rpHead('Laporan per rombel',`Rombel ${c.name}`,`Kelas ${g||'—'} · ${rpTeacher(c)?'Wali kelas '+rpTeacher(c):'Wali kelas belum diisi'} · ${A.n} anak aktif`)}${rpKpi([['Anak aktif',A.n,'Mengikuti hafalan'],['Capaian rata-rata',A.avg+'%','Rata-rata rombel'],['Siap ujian',A.ready,'Menunggu ujian kenaikan'],['Tamat',A.tamat,'Menuntaskan level terakhir']])}${rpSec('Sebaran level','Komposisi level hafalan anak di rombel ini',`<div class="rp-stack">${stack}</div><div class="rp-legend">${legend}</div>`)}${rpSec('Daftar anak','Capaian hafalan masing-masing anak',rpStuTable(st))}${rpSign([rpSignKepala(),...rpSignPai(c)])}${rpFoot()}</section>`;
}
function rpPageAnak(s){
 const x=rpGet(s),c=rpClass(s.classId),lv=lvLabel(x.level).split(' · ')[1]||'';
 const sur=x.surahs.map((z,i)=>`<tr><td class="c">${i+1}</td><td><b>${esc(z.name)}</b></td><td class="c">${z.max}</td><td class="c">${z.hafal}</td><td class="c">${rpSurahPill(z.status)}</td><td class="bc">${rpBar(z.max?Math.round(z.hafal/z.max*100):0)}</td></tr>`).join('');
 const hist=logs.filter(l=>!l.auto&&String(l.studentId)===String(s.id)).slice().sort((a,b)=>String(a.date).localeCompare(String(b.date))||(Number(a.id)-Number(b.id))).slice(-5).reverse();
 const hrows=hist.map(l=>`<tr><td>${esc(niceDate(l.date))}</td><td>${esc(l.surah)}</td><td class="c">${l.from}–${l.to}</td><td>${esc(l.status)}</td><td>${esc(l.note&&!/^Level /.test(l.note)?l.note:'—')}</td></tr>`).join('');
 const riwayat=hist.length?`<table class="rp-t"><thead><tr><th>Tanggal</th><th>Surat</th><th class="c">Ayat</th><th>Hasil</th><th>Catatan</th></tr></thead><tbody>${hrows}</tbody></table>`:'<div class="rp-empty">Belum ada riwayat setoran.</div>';
 return `<section class="page">${rpBism()}${rpHead('Rapor hafalan anak',s.name,`${s.nis?'NIS '+s.nis+' · ':''}${c?c.name:'Tanpa rombel'} · Kelas ${rpGradeOf(c)||'—'} · ${lvLabel(x.level)}`)}${rpKpi([['Level hafalan','Level '+x.level,lv],['Capaian',x.pct+'%',`${x.hafal} dari ${x.total} ayat`],['Surat tuntas',`${x.done}/${x.count}`,'Surat dalam level'],['Status',rpStatusInfo(x)[0],x.ready?'Siap ujian kenaikan level':'Terus menambah hafalan']])}${pmRaporSec(s)}${rpSec('Progres per surat','Ayat yang sudah hafal pada setiap surat',`<table class="rp-t"><thead><tr><th class="c" style="width:30px">No</th><th>Surat</th><th class="c">Ayat</th><th class="c">Hafal</th><th class="c">Keterangan</th><th>Progres</th></tr></thead><tbody>${sur}</tbody></table>`)}${pgRaporSec(s)}${rpSec('Riwayat setoran terakhir','Lima catatan setoran terbaru',riwayat)}${rpSign([rpSignKepala(),...rpSignPai(c)])}${rpFoot()}</section>`;
}
function rpPage(t){
 if(t.k==='sekolah')return rpPageSekolah();
 if(t.k==='level')return rpPageLevel(t.v);
 if(t.k==='kelas')return rpPageKelas(t.v);
 if(t.k==='rombel')return rpPageRombel(t.v);
 return rpPageAnak(t.v);
}
function rpDoc(title,body,count){
 const school=String(settings.school||'').replace(/["\\]/g,'');
 const kl=String(kopCur().logo||'').replace(/["'\\()]/g,'');
 return `<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Amiri:wght@400;700&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>${RP_DOC_CSS.replace('__SCHOOL__',()=>school).replace('__KOPLOGO__',()=>kl)}</style></head><body><div class="rp-toolbar"><div><b>${esc(title)}</b><span>${count} laporan · pilih Cetak / Simpan PDF, lalu atur tujuan ke Simpan sebagai PDF bila perlu</span></div><div><button onclick="window.print()">Cetak / Simpan PDF</button><button class="ghost" onclick="window.close()">Tutup</button></div></div>${body}</body></html>`;
}
function rpGenerate(){
 const T=rpTargets();
 if(!T.length){toast('Belum ada anak aktif untuk pilihan ini.');return}
 RPCACHE=new Map();rpActive().forEach(s=>RPCACHE.set(String(s.id),rpStat(s)));
 const label={sekolah:'Laporan Satu Sekolah',level:'Laporan Per Level',kelas:'Laporan Per Kelas',rombel:'Laporan Per Rombel',anak:'Rapor Hafalan Anak'}[rpState.type];
 const html=rpDoc(`${label} · ${settings.school||''}`,T.map(rpPage).join(''),T.length);
 const w=window.open('','_blank');
 if(!w){toast('Pop-up diblokir browser. Izinkan pop-up lalu coba lagi.');return}
 w.document.open();w.document.write(html);w.document.close();
  toast('Laporan dibuka di tab baru.');
}

/* ---------- panel pilihan di menu Laporan ---------- */
function rpSetType(t){rpState.type=t;renderPrintPanel()}
function rpSet(k,v){rpState[k]=v;if(k==='anakRombel')rpState.anak='all';renderPrintPanel()}
function rpSetGroup(g){rpState.group=g;renderPrintPanel()}
function rpFormHTML(){
 const T=rpState.type,cls=rpSortedClasses(),opt=(v,l,cur)=>`<option value="${esc(v)}"${String(cur)===String(v)?' selected':''}>${esc(l)}</option>`;
 let scope='';
 if(T==='sekolah'){
  scope=`<div class="formrow full"><label>Kelompokkan menurut</label><div class="rp-seg"><button class="${rpState.group==='level'?'active':''}" onclick="rpSetGroup('level')">Level hafalan (rekomendasi)</button><button class="${rpState.group==='kelas'?'active':''}" onclick="rpSetGroup('kelas')">Tingkat kelas</button></div><p class="hint">Level menentukan target surat, sehingga paling tepat untuk melihat capaian hafalan. Pilih tingkat kelas untuk rekap administratif.</p></div>`;
 }else if(T==='level'){
  scope=`<div class="formrow"><label>Level hafalan</label><select class="field" onchange="rpSet('level',this.value)">${opt('all','Semua level',rpState.level)}${rpLevels().map(l=>opt(l,lvLabel(l),rpState.level)).join('')}</select></div>`;
 }else if(T==='kelas'){
  scope=`<div class="formrow"><label>Tingkat kelas</label><select class="field" onchange="rpSet('grade',this.value)">${opt('all','Semua kelas',rpState.grade)}${rpGrades().map(g=>opt(g,'Kelas '+g,rpState.grade)).join('')}</select></div>`;
 }else if(T==='rombel'){
  scope=`<div class="formrow"><label>Rombel</label><select class="field" onchange="rpSet('rombel',this.value)">${opt('all','Semua rombel',rpState.rombel)}${cls.map(c=>opt(c.id,c.name,rpState.rombel)).join('')}</select></div>`;
 }else{
  const ar=rpState.anakRombel,pool=rpMembers({k:'sekolah'}).filter(s=>ar==='all'||String(s.classId)===String(ar));
  scope=`<div class="formrow"><label>Rombel</label><select class="field" onchange="rpSet('anakRombel',this.value)">${opt('all','Semua rombel',ar)}${cls.map(c=>opt(c.id,c.name,ar)).join('')}</select></div><div class="formrow full"><label>Anak</label><select class="field" onchange="rpSet('anak',this.value)">${opt('all',`Semua anak (${pool.length} anak, satu halaman per anak)`,rpState.anak)}${pool.map(s=>opt(s.id,s.name+' — '+((rpClass(s.classId)||{}).name||''),rpState.anak)).join('')}</select></div>`;
 }
 return scope+`<div class="formrow full" style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap"><p class="hint" style="margin:0;max-width:640px">Tanda tangan memakai nama wali kelas dari data rombel dan nama guru tahfidz dari Pengaturan. Nama dan NIP kepala sekolah diatur di menu Pengaturan. Nama yang masih kosong akan dicetak sebagai garis untuk diisi tangan.</p><button class="btn light small" onclick="go('pengaturan')">Buka Pengaturan</button></div>`;
}
function renderPrintPanel(){
 if(!window.RP_TYPES||!document.getElementById('rpTypes'))return;
  document.getElementById('rpTypes').innerHTML=RP_TYPES.map(t=>`<button class="rp-type${rpState.type===t.id?' active':''}" onclick="rpSetType('${t.id}')">${t.badge?`<span class="rp-badge">${t.badge}</span>`:''}<span class="rp-ic"><svg viewBox="0 0 24 24" aria-hidden="true">${t.icon}</svg></span><b>${t.label}</b><p>${t.desc}</p></button>`).join('');
 document.getElementById('rpForm').innerHTML=rpFormHTML();
 const T=rpTargets(),n=T.reduce((a,t)=>a+rpMembers(t).length,0),info=RP_TYPES.find(t=>t.id===rpState.type);
 document.getElementById('rpSummary').innerHTML=T.length?`Akan dicetak <b>${T.length} ${info.unit}</b>${rpState.type==='anak'?'':` untuk <b>${n} anak</b>`}`:'Belum ada data untuk pilihan ini.';
}

/* ---------- menu Laporan: ringkasan + tabel (memakai perhitungan yang sama dengan cetak) ---------- */
function renderReports(){
 if(typeof hfSurahStats!=='function'||typeof ujState!=='function')return;
 RPCACHE=new Map();const act=rpActive();act.forEach(s=>RPCACHE.set(String(s.id),rpStat(s)));
 const st=act.map(rpGet);
 $('reportLogs').textContent=activeLogs().length;
 $('reportActive').textContent=new Set(activeLogs().map(l=>l.studentId)).size;
 $('reportDone').textContent=st.filter(x=>x.pct>=100).length;
 $('reportReview').textContent=activeLogs().filter(l=>needsRepeat(l.status)).length;
 $('reportRows').innerHTML=rpSortStudents(act).map(s=>{const x=rpGet(s),c=rpClass(s.classId);return `<tr><td><b>${esc(s.name)}</b>${s.nis?`<br><small style="color:#6b7280">NIS ${esc(s.nis)}</small>`:''}</td><td>${esc(c?c.name:'—')}</td><td>${rpLv(x.level)}</td><td class="num">${x.done}/${x.count} surat</td><td class="num">${x.hafal}/${x.total} ayat</td><td class="progresscell"><div class="bar"><span style="width:${x.pct}%"></span></div><small>${x.pct}%</small></td></tr>`}).join('');
 renderPrintPanel();
}

/* ===== Kop surat laporan (diatur di menu Pengaturan) ===== */
var KOP_DEFAULT={lines:[
 {t:'PEMERINTAH KABUPATEN KARANGANYAR',s:11,b:true,i:false},
 {t:'DINAS PENDIDIKAN DAN KEBUDAYAAN',s:11,b:true,i:false},
 {t:'SEKOLAH DASAR NEGERI 01 PAPAHAN',s:15,b:true,i:false},
 {t:'Alamat : Jl. Lawu Barat, Ngablak RT 01 / IX Papahan, Tasikmadu, Karanganyar Telp 0271 6498034',s:8.5,b:false,i:false,f:true},
 {t:'E-mail : sdnpapahan01@gmail.com, Website : http://www.sdn01papahan.net, Weblog : sdn01papahan.sch.id',s:8.5,b:false,i:false,f:true}
],logo:null,logoMm:22,rule:true};
var kopDraft=null;
function kopNorm(k){
 const d=JSON.parse(JSON.stringify(KOP_DEFAULT));d.logo=schoolLogoCur();
 if(!k||typeof k!=='object')return d;
 const lines=Array.isArray(k.lines)&&k.lines.length?k.lines.slice(0,8).map(l=>({t:String(l&&l.t!=null?l.t:''),s:Math.min(24,Math.max(6,+(l&&l.s)||11)),b:!!(l&&l.b),i:!!(l&&l.i),f:!!(l&&l.f)})):d.lines;
 return{lines,noLogo:!!k.noLogo&&!k.logo,logo:k.logo||(k.noLogo?null:schoolLogoCur()),logoMm:Math.min(40,Math.max(12,+k.logoMm||22)),rule:k.rule!==false};
}
function kopCur(){return kopNorm(settings.kop)}
function kopHTML(k,mode){
 const mm=k.logoMm||22;
 let logoEl='';
 if(k.logo)logoEl=mode==='doc'?`<i class="kop-logo" style="--kmm:${mm}mm"></i>`:`<img class="kop-logo-img" src="${k.logo}" alt="" style="width:${mm}mm;height:${mm}mm;object-fit:contain;display:block;flex-shrink:0">`;
 const spacer=k.logo?`<span class="kop-spacer" style="width:${mm}mm"></span>`:'';
 const lineHTML=l=>`<div class="kop-line" style="font-size:${l.s}pt;font-weight:${l.b?700:400};font-style:${l.i?'italic':'normal'}">${String(l.t).trim()?esc(l.t):'&nbsp;'}</div>`;
 const runs=[];
 k.lines.forEach(l=>{const last=runs[runs.length-1];if(last&&last.full===!!l.f)last.items.push(l);else runs.push({full:!!l.f,items:[l]})});
 if(k.logo&&!runs.some(r=>!r.full))runs.unshift({full:false,items:[]});
 let logoDone=!k.logo,html='';
 runs.forEach(r=>{
  if(r.full){html+=`<div class="kop-full">${r.items.map(lineHTML).join('')}</div>`;return}
  const lg=logoDone?'':logoEl,sp=logoDone?'':spacer;logoDone=true;
  html+=`<div class="kop">${lg}<div class="kop-text">${r.items.map(lineHTML).join('')}</div>${sp}</div>`;
 });
 return `<div class="kop-wrap">${html}${k.rule?'<div class="kop-rule"></div>':''}</div>`;
}
function kopOpen(){
 kopDraft=kopNorm(settings.kop);
 const m=document.getElementById('kopMm'),r=document.getElementById('kopRule');
 if(m)m.value=kopDraft.logoMm;if(r)r.checked=kopDraft.rule;
 kopRenderEditor();
}
function kopPreview(){const el=document.getElementById('kopPreview');if(el&&kopDraft)el.innerHTML=kopHTML(kopDraft,'app')}
function kopRenderEditor(){
 const box=document.getElementById('kopLines');if(!box||!kopDraft)return;
 const n=kopDraft.lines.length;
 box.innerHTML=kopDraft.lines.map((l,i)=>`<div class="kop-row"><span class="kop-n">${i+1}</span><input class="field kop-t" value="${esc(l.t)}" placeholder="Teks baris ${i+1}" oninput="kopEdit(${i},'t',this.value)"><label class="kop-chk">Ukuran <input class="field kop-s" type="number" min="6" max="24" step="0.5" value="${l.s}" oninput="kopEdit(${i},'s',this.value)"> pt</label><label class="kop-chk"><input type="checkbox"${l.b?' checked':''} onchange="kopEdit(${i},'b',this.checked)"> Tebal</label><label class="kop-chk"><input type="checkbox"${l.i?' checked':''} onchange="kopEdit(${i},'i',this.checked)"> Miring</label><label class="kop-chk" title="Tampil di bawah logo, memanjang selebar kertas"><input type="checkbox"${l.f?' checked':''} onchange="kopEdit(${i},'f',this.checked)"> Lebar penuh</label><button type="button" class="kop-del" title="Hapus baris" onclick="kopDelLine(${i})"${n<=1?' disabled':''}>×</button></div>`).join('')
  +`<button type="button" class="btn secondary small" onclick="kopAddLine()"${n>=8?' disabled':''}>+ Tambah baris</button>`;
 const lg=document.getElementById('kopLogoBox');
 if(lg)lg.innerHTML=kopDraft.logo?`<img src="${kopDraft.logo}" alt="Logo kop" class="kop-lg-img">`:'<span class="hint">Belum ada logo kop.</span>';
 kopPreview();
}
function kopEdit(i,f,v){const l=kopDraft&&kopDraft.lines[i];if(!l)return;if(f==='s')l.s=Math.min(24,Math.max(6,+v||11));else l[f]=v;kopPreview()}
function kopSetOpt(f,v){if(!kopDraft)return;if(f==='logoMm')kopDraft.logoMm=Math.min(40,Math.max(12,+v||22));else kopDraft[f]=!!v;kopPreview()}
function kopAddLine(){if(!kopDraft||kopDraft.lines.length>=8)return;kopDraft.lines.push({t:'',s:11,b:false,i:false,f:false});kopRenderEditor()}
function kopDelLine(i){if(!kopDraft||kopDraft.lines.length<=1)return;kopDraft.lines.splice(i,1);kopRenderEditor()}
function kopLogoRemove(){if(!kopDraft)return;kopDraft.logo=null;kopDraft.noLogo=true;kopRenderEditor()}
function kopLogoDefault(){if(!kopDraft)return;kopDraft.logo=schoolLogoCur();kopDraft.noLogo=false;kopRenderEditor()}
function kopPickLogo(inp){
 const f=inp&&inp.files&&inp.files[0];if(!f||!kopDraft)return;
 const r=new FileReader();
 if(f.type==='image/svg+xml'){
  if(f.size>400000){toast('SVG terlalu besar (maks 400 KB).');return}
  r.onload=()=>{kopDraft.logo=r.result;kopRenderEditor();toast('Logo kop dipasang. Klik Simpan Kop untuk menyimpan.')};
  r.readAsDataURL(f);return;
 }
 r.onload=()=>{
  const im=new Image();
  im.onload=()=>{
   const max=480,k=Math.min(1,max/Math.max(im.width,im.height)),c=document.createElement('canvas');
   c.width=Math.max(1,Math.round(im.width*k));c.height=Math.max(1,Math.round(im.height*k));
   c.getContext('2d').drawImage(im,0,0,c.width,c.height);
   kopDraft.logo=c.toDataURL('image/png');kopRenderEditor();
   toast('Logo kop dipasang. Klik Simpan Kop untuk menyimpan.');
  };
  im.onerror=()=>toast('Berkas gambar tidak bisa dibaca.');
  im.src=r.result;
 };
 r.readAsDataURL(f);
}
function kopSave(){
 if(!kopDraft)return;
 {const n=kopNorm(kopDraft);if(n.logo===schoolLogoCur())n.logo=null;settings.kop=n}
 try{save()}catch(e){toast('Penyimpanan penuh. Coba gunakan logo dengan ukuran lebih kecil.');return}
 kopRenderSummary();kopModalClose();
 toast('Kop surat disimpan. Laporan berikutnya memakai kop ini.');
}
function kopReset(){
 if(!kopDraft)return;
 const logo=kopDraft.logo;
 kopDraft=JSON.parse(JSON.stringify(KOP_DEFAULT));kopDraft.logo=logo;
 const m=document.getElementById('kopMm'),r=document.getElementById('kopRule');
 if(m)m.value=kopDraft.logoMm;if(r)r.checked=kopDraft.rule;
 kopRenderEditor();toast('Kop dikembalikan ke bawaan. Klik Simpan Kop untuk menerapkan.');
}
