function openModal(title,fields,mode,id){modalMode=mode;$('modalSubmit').textContent='Simpan Catatan';editingId=id??null;$('modalTitle').textContent=title;$('modalFields').innerHTML=fields;$('modalback').classList.add('open')};function closeModal(){$('modalback').classList.remove('open')}
function classOptions(selected){return classes.map(c=>`<option value="${c.id}" ${c.id==selected?'selected':''}>${esc(c.name)}</option>`).join('')}function surahOptions(selected){return surahs.map(s=>`<option value="${esc(s.name)}" ${s.name===selected?'selected':''}>${esc(s.name)}</option>`).join('')}
function openProgress(studentId=null,classId=null){let s=students.find(x=>x.id===studentId);let f=`<div class="formgrid"><div class="formrow full"><label>Nama anak *</label><select class="field" style="width:100%" name="studentId" required onchange="updateProgressTarget(this.value)"><option value="">Pilih anak</option>${students.filter(x=>!classId||x.classId===classId).map(x=>`<option value="${x.id}" ${x.id===studentId?'selected':''}>${esc(x.name)} — ${esc(className(x.classId))}</option>`).join('')}</select></div><div class="formrow"><label>Tanggal setoran *</label><input type="date" name="date" value="${today()}" required></div><div class="formrow"><label>Surat *</label><select name="surah" required>${surahOptions(s?.surah||surahs[0]?.name)}</select></div><div class="formrow"><label>Dari ayat *</label><input name="from" type="number" min="1" value="${s?.done?Math.min(s.target,s.done+1):1}" required></div><div class="formrow"><label>Sampai ayat *</label><input name="to" type="number" min="1" value="${s?.target||5}" required></div><div class="formrow"><label>Hasil setoran *</label><select name="status"><option>Lancar</option><option>Perlu murajaah</option><option>Belum lancar</option></select></div><div class="formrow"><label>Tambahan ayat dikuasai</label><input name="doneAdd" type="number" min="0" value="0"><span class="hint">Jumlah ayat baru yang sudah dikuasai untuk memperbarui capaian.</span></div><div class="formrow full"><label>Catatan guru (opsional)</label><textarea name="note" rows="2" placeholder="Contoh: makhraj perlu diperbaiki, sudah lancar tanpa bantuan..."></textarea></div></div>`;openModal('Catat Kemajuan Hafalan',f,'progress')}
function updateProgressTarget(id){let s=students.find(x=>x.id==id);if(!s)return;let form=$('modalForm');form.elements.from.value=(s.done||0)+1;form.elements.to.value=s.target;form.elements.surah.value=s.surah}
function openStudent(){let f=`<div class="formgrid"><div class="formrow full"><label>Nama lengkap anak *</label><input name="name" required placeholder="Nama anak"></div><div class="formrow"><label>Kelas *</label><select name="classId" required>${classOptions(classes[0]?.id)}</select></div><div class="formrow"><label>Target surat *</label><select name="surah" required>${surahOptions(surahs[0]?.name)}</select></div><div class="formrow"><label>Ayat mulai</label><input name="start" type="number" min="1" value="1" required></div><div class="formrow"><label>Target sampai ayat</label><input name="target" type="number" min="1" value="5" required></div></div>`;openModal('Tambah Data Anak',f,'student')}
function editStudent(id){let s=students.find(x=>x.id===id);if(!s)return;let f=`<div class="formgrid"><div class="formrow full"><label>Nama lengkap anak *</label><input name="name" required value="${esc(s.name)}"></div><div class="formrow"><label>Kelas *</label><select name="classId">${classOptions(s.classId)}</select></div><div class="formrow"><label>Target surat *</label><select name="surah">${surahOptions(s.surah)}</select></div><div class="formrow"><label>Ayat mulai</label><input name="start" type="number" min="1" value="${s.start}" required></div><div class="formrow"><label>Target sampai ayat</label><input name="target" type="number" min="1" value="${s.target}" required></div><div class="formrow full"><label>Ayat yang sudah dikuasai</label><input name="done" type="number" min="0" value="${s.done||0}" required></div></div>`;openModal('Edit Data Anak',f,'editStudent',id)}
function openClass(id=null){let c=classes.find(x=>x.id===id);let f=`<div class="formgrid"><div class="formrow"><label>Tingkat kelas *</label><select name="grade" required><option value="1" ${String(c?.grade||classGradeNum(c))==='1'?'selected':''}>Kelas 1</option><option value="2" ${String(c?.grade||classGradeNum(c))==='2'?'selected':''}>Kelas 2</option><option value="3" ${String(c?.grade||classGradeNum(c))==='3'?'selected':''}>Kelas 3</option><option value="4" ${String(c?.grade||classGradeNum(c))==='4'?'selected':''}>Kelas 4</option><option value="5" ${String(c?.grade||classGradeNum(c))==='5'?'selected':''}>Kelas 5</option><option value="6" ${String(c?.grade||classGradeNum(c))==='6'?'selected':''}>Kelas 6</option></select></div><div class="formrow"><label>Nama rombel *</label><input name="name" required value="${esc(c?.name||'')}" placeholder="Contoh: 1A, 1B, 1C"></div><div class="formrow"><label>Tahun ajaran *</label><input name="year" required value="${esc(c?.year||settings.year||'2026/2027')}" placeholder="2026/2027"></div><div class="formrow"><label>Wali kelas / guru</label><input name="teacher" value="${esc(c?.teacher||'')}" placeholder="Nama guru"></div><div class="formrow"><label>Level / kelompok hafalan</label><select name="level">${Object.keys(HAFALAN_CURRICULUM).map(l=>`<option value="${l}" ${(c?.level||'1')===l?'selected':''}>${lvLabel(l)}</option>`).join('')}</select></div><div class="formrow"><label>Deskripsi</label><input name="desc" value="${esc(c?.desc||'')}" placeholder="Fokus hafalan kelas"></div></div><p class="hint" style="margin-top:12px">Contoh: tingkat 1 dengan nama rombel 1A, 1B, atau 1C. Setiap rombel memiliki data peserta didik dan capaian masing-masing.</p>`;openModal(c?'Edit Rombel':'Tambah Rombel',f,'class',id)}
function classGradeNum(c){let m=String(c?.name||'').match(/\d+/);return m?m[0]:'1'}
function openSurah(){let f=`<div class="formgrid"><div class="formrow full"><label>Nama surat / target *</label><input name="name" required placeholder="Contoh: Al-‘Asr"></div><div class="formrow"><label>Ayat awal *</label><input name="start" type="number" min="1" value="1" required></div><div class="formrow"><label>Ayat akhir *</label><input name="end" type="number" min="1" value="3" required></div><div class="formrow full"><label>Keterangan</label><input name="note" placeholder="Catatan target (opsional)"></div></div>`;openModal('Tambah Target Surat & Ayat',f,'surah')}
function editSurah(id){let s=surahs.find(x=>x.id===id);let f=`<div class="formgrid"><div class="formrow full"><label>Nama surat / target *</label><input name="name" required value="${esc(s.name)}"></div><div class="formrow"><label>Ayat awal *</label><input name="start" type="number" min="1" value="${s.start}" required></div><div class="formrow"><label>Ayat akhir *</label><input name="end" type="number" min="1" value="${s.end}" required></div><div class="formrow full"><label>Keterangan</label><input name="note" value="${esc(s.note||'')}"></div></div>`;openModal('Edit Target Surat & Ayat',f,'editSurah',id)}
async function deleteSurah(id){if(!await HK.confirm('Hapus target surat ini? Data capaian lama tidak otomatis dihapus.','Hapus'))return;const gone=surahs.find(s=>s.id===id),at=surahs.indexOf(gone);surahs=surahs.filter(s=>s.id!==id);save();renderSurahs();
 HKFB.undoable('Target surat dihapus.',()=>{if(gone&&!surahs.some(s=>s.id===id))surahs.splice(Math.min(at,surahs.length),0,gone);save();renderSurahs()})}
function submitModal(e){e.preventDefault();let f=new FormData(e.target),v=Object.fromEntries(f.entries());if(modalMode==='progress'){let s=students.find(x=>x.id==v.studentId);if(!s){toast('Pilih nama anak terlebih dahulu.');return}let from=+v.from,to=+v.to;if(from<1||to<from){toast('Rentang ayat tidak valid.');return}logs.push({id:Date.now(),studentId:s.id,studentName:s.name,classId:s.classId,date:v.date,surah:v.surah,from,to,status:v.status,note:v.note||''});if(+v.doneAdd>0)s.done=Math.min(+s.target,(+s.done||0)+(+v.doneAdd));s.surah=v.surah;closeModal();refresh();toast('Kemajuan hafalan berhasil dicatat.')}else if(modalMode==='student'||modalMode==='editStudent'){let data={name:v.name.trim(),classId:+v.classId,surah:v.surah,start:+v.start,target:+v.target,done:+(v.done||0)};if(data.target<data.start){toast('Target ayat harus sama atau lebih besar dari ayat awal.');return}if(modalMode==='student')students.push({id:Date.now(),...data});else Object.assign(students.find(s=>s.id===editingId),data);closeModal();refresh();toast('Data anak berhasil disimpan.')}else if(modalMode==='class'){if(classes.some(c=>String(c.year||settings.year)===String(v.year||settings.year)&&c.name.toLowerCase()===v.name.trim().toLowerCase()&&c.id!==editingId)){toast('Nama rombel sudah digunakan pada tahun ajaran tersebut.');return}let data={name:v.name.trim(),grade:+v.grade,year:v.year.trim(),teacher:v.teacher.trim(),level:v.level,desc:v.desc};if(editingId)Object.assign(classes.find(c=>c.id===editingId),data);else classes.push({id:Date.now(),...data});closeModal();refresh();toast('Data rombel berhasil disimpan.')}else if(modalMode==='surah'||modalMode==='editSurah'){if(+v.end<+v.start){toast('Ayat akhir harus lebih besar atau sama dengan ayat awal.');return}let data={name:v.name.trim(),start:+v.start,end:+v.end,note:v.note};if(modalMode==='surah')surahs.push({id:Date.now(),...data});else{Object.assign(surahs.find(s=>s.id===editingId),data);students.forEach(s=>{if(s.surah===data.name)s.target=data.end})}closeModal();refresh();toast('Target surat berhasil disimpan.')}}
